export const mobileAssets={"/admin/index.html":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Rekha WhatsApp Admin</title><link rel=\"stylesheet\" href=\"/admin/style.css\"></head><body>\n<header><div class=\"logo\">R</div><div><h1>Rekha WhatsApp</h1><small id=\"connection\">Private admin</small></div><button id=\"refresh\" aria-label=\"Refresh\">↻</button></header>\n<section id=\"login\"><h2>Your private admin</h2><p>On your computer, open the private WhatsApp panel → Admin app → Generate sign-in code.</p><form id=\"loginForm\"><label for=\"code\">One-use sign-in code</label><input id=\"code\" type=\"text\" autocomplete=\"off\" autocapitalize=\"characters\" maxlength=\"24\" placeholder=\"XXXX-XXXX-XXXX-XXXX-XXXX\" required><button type=\"submit\">Sign in</button></form><p>The code expires after 10 minutes. Your WhatsApp pairing code is different.</p></section>\n<div id=\"dashboard\" hidden><nav><button id=\"showInbox\">Customers</button><button id=\"showHealth\">Backend</button><button id=\"toggle\">Pause funnel</button><button id=\"logout\">Sign out</button></nav><p id=\"summary\" class=\"summary\"></p>\n<section id=\"health\" hidden><h2>Backend health</h2><div id=\"metrics\"></div><p id=\"warnings\"></p><p>Provider-wide usage and bills: <a href=\"https://dash.cloudflare.com/\" target=\"_blank\" rel=\"noreferrer\">Cloudflare</a>. Request totals and R2 bills are not estimated here.</p></section>\n<section id=\"inbox\"><h2>Customers</h2><div id=\"contacts\"></div><button id=\"moreContacts\" hidden>Older customers</button><button id=\"latestContacts\">Latest customers</button></section>\n<section id=\"chat\" hidden><button id=\"back\">‹ Customers</button><h2 id=\"chatName\"></h2><p id=\"chatDetails\"></p><div class=\"actions\"><button id=\"pause\">Pause automation</button><button id=\"payment\">Verify payment</button><button id=\"delete\" class=\"danger\">Delete content</button></div><button id=\"olderMessages\" hidden>Older messages</button><div id=\"messages\"></div><div id=\"uncertain\"></div><form id=\"composer\"><label class=\"sr\" for=\"reply\">Reply</label><textarea id=\"reply\" rows=\"2\" maxlength=\"8000\" placeholder=\"Write a reply…\" required></textarea><button id=\"send\">Send</button></form></section>\n</div><p id=\"notice\" role=\"status\" hidden></p><script type=\"module\" src=\"/admin/app.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/admin":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Rekha WhatsApp Admin</title><link rel=\"stylesheet\" href=\"/admin/style.css\"></head><body>\n<header><div class=\"logo\">R</div><div><h1>Rekha WhatsApp</h1><small id=\"connection\">Private admin</small></div><button id=\"refresh\" aria-label=\"Refresh\">↻</button></header>\n<section id=\"login\"><h2>Your private admin</h2><p>On your computer, open the private WhatsApp panel → Admin app → Generate sign-in code.</p><form id=\"loginForm\"><label for=\"code\">One-use sign-in code</label><input id=\"code\" type=\"text\" autocomplete=\"off\" autocapitalize=\"characters\" maxlength=\"24\" placeholder=\"XXXX-XXXX-XXXX-XXXX-XXXX\" required><button type=\"submit\">Sign in</button></form><p>The code expires after 10 minutes. Your WhatsApp pairing code is different.</p></section>\n<div id=\"dashboard\" hidden><nav><button id=\"showInbox\">Customers</button><button id=\"showHealth\">Backend</button><button id=\"toggle\">Pause funnel</button><button id=\"logout\">Sign out</button></nav><p id=\"summary\" class=\"summary\"></p>\n<section id=\"health\" hidden><h2>Backend health</h2><div id=\"metrics\"></div><p id=\"warnings\"></p><p>Provider-wide usage and bills: <a href=\"https://dash.cloudflare.com/\" target=\"_blank\" rel=\"noreferrer\">Cloudflare</a>. Request totals and R2 bills are not estimated here.</p></section>\n<section id=\"inbox\"><h2>Customers</h2><div id=\"contacts\"></div><button id=\"moreContacts\" hidden>Older customers</button><button id=\"latestContacts\">Latest customers</button></section>\n<section id=\"chat\" hidden><button id=\"back\">‹ Customers</button><h2 id=\"chatName\"></h2><p id=\"chatDetails\"></p><div class=\"actions\"><button id=\"pause\">Pause automation</button><button id=\"payment\">Verify payment</button><button id=\"delete\" class=\"danger\">Delete content</button></div><button id=\"olderMessages\" hidden>Older messages</button><div id=\"messages\"></div><div id=\"uncertain\"></div><form id=\"composer\"><label class=\"sr\" for=\"reply\">Reply</label><textarea id=\"reply\" rows=\"2\" maxlength=\"8000\" placeholder=\"Write a reply…\" required></textarea><button id=\"send\">Send</button></form></section>\n</div><p id=\"notice\" role=\"status\" hidden></p><script type=\"module\" src=\"/admin/app.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/admin/":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Rekha WhatsApp Admin</title><link rel=\"stylesheet\" href=\"/admin/style.css\"></head><body>\n<header><div class=\"logo\">R</div><div><h1>Rekha WhatsApp</h1><small id=\"connection\">Private admin</small></div><button id=\"refresh\" aria-label=\"Refresh\">↻</button></header>\n<section id=\"login\"><h2>Your private admin</h2><p>On your computer, open the private WhatsApp panel → Admin app → Generate sign-in code.</p><form id=\"loginForm\"><label for=\"code\">One-use sign-in code</label><input id=\"code\" type=\"text\" autocomplete=\"off\" autocapitalize=\"characters\" maxlength=\"24\" placeholder=\"XXXX-XXXX-XXXX-XXXX-XXXX\" required><button type=\"submit\">Sign in</button></form><p>The code expires after 10 minutes. Your WhatsApp pairing code is different.</p></section>\n<div id=\"dashboard\" hidden><nav><button id=\"showInbox\">Customers</button><button id=\"showHealth\">Backend</button><button id=\"toggle\">Pause funnel</button><button id=\"logout\">Sign out</button></nav><p id=\"summary\" class=\"summary\"></p>\n<section id=\"health\" hidden><h2>Backend health</h2><div id=\"metrics\"></div><p id=\"warnings\"></p><p>Provider-wide usage and bills: <a href=\"https://dash.cloudflare.com/\" target=\"_blank\" rel=\"noreferrer\">Cloudflare</a>. Request totals and R2 bills are not estimated here.</p></section>\n<section id=\"inbox\"><h2>Customers</h2><div id=\"contacts\"></div><button id=\"moreContacts\" hidden>Older customers</button><button id=\"latestContacts\">Latest customers</button></section>\n<section id=\"chat\" hidden><button id=\"back\">‹ Customers</button><h2 id=\"chatName\"></h2><p id=\"chatDetails\"></p><div class=\"actions\"><button id=\"pause\">Pause automation</button><button id=\"payment\">Verify payment</button><button id=\"delete\" class=\"danger\">Delete content</button></div><button id=\"olderMessages\" hidden>Older messages</button><div id=\"messages\"></div><div id=\"uncertain\"></div><form id=\"composer\"><label class=\"sr\" for=\"reply\">Reply</label><textarea id=\"reply\" rows=\"2\" maxlength=\"8000\" placeholder=\"Write a reply…\" required></textarea><button id=\"send\">Send</button></form></section>\n</div><p id=\"notice\" role=\"status\" hidden></p><script type=\"module\" src=\"/admin/app.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/admin/style.css":{"body":":root{font-family:system-ui,Segoe UI,sans-serif;color:#163d31;background:#f2f6f2}*{box-sizing:border-box}body{margin:0}header{display:flex;align-items:center;gap:12px;padding:18px;background:#125b48;color:white;position:sticky;top:0;z-index:2}.logo{display:grid;place-items:center;border:1px solid #ffffff66;border-radius:14px;width:42px;height:42px;font:28px Georgia}h1{font-size:19px;margin:0}header small{font-size:12px;opacity:.8}header button{margin-left:auto;background:#ffffff15;border-color:#ffffff44;color:white;font-size:22px}h2{font-size:19px;margin:10px 0}section{max-width:880px;margin:16px auto;padding:18px;background:white;border-radius:16px}#login{max-width:460px;margin:32px auto}p{font-size:13px;line-height:1.6;color:#657b70}button,input,textarea{font:inherit}button{cursor:pointer;border:1px solid #c9dcd0;border-radius:9px;padding:10px 13px;color:#16543f;background:white}button:disabled{opacity:.45;cursor:default}button:active{background:#e1eee4}input,textarea{border:1px solid #c8d8ce;border-radius:10px;padding:12px;min-width:0}textarea{width:100%;resize:vertical}#loginForm{display:grid;gap:14px;margin:24px 0}#loginForm button,#send{background:#146044;color:white;border-color:#146044}label{font-size:13px}nav{display:flex;gap:8px;padding:12px;overflow:auto;background:white}nav button{white-space:nowrap;font-size:12px}.summary{padding:0 18px}.contact{display:block;width:100%;text-align:left;border:0;border-radius:0;border-bottom:1px solid #eaf0eb;padding:16px 0}.contact strong,.contact small{display:block}.contact small{font-size:12px;color:#6e8276;margin-top:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.contact b{float:right;border-radius:20px;padding:3px 8px;background:#d9f3df;font-size:11px}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{font-size:12px}.danger{color:#a43e33}#messages{display:flex;flex-direction:column;gap:12px;background:#eff4ec;padding:16px;margin:14px -8px;border-radius:12px;min-height:180px}.message{align-self:flex-start;max-width:90%;border-radius:12px;background:white;padding:12px;overflow-wrap:anywhere;border:1px solid #e0e8dd}.message.out{align-self:flex-end;background:#d8efcf}.body{white-space:pre-wrap;font-size:14px;line-height:1.6}.meta{font-size:10px;color:#728572;margin-top:8px;text-align:right}a{color:#126c4b}.message a{display:block;margin-top:8px;font-size:12px}#composer{display:flex;align-items:flex-end;gap:9px;position:sticky;bottom:0;background:white;padding:12px 0}#notice{position:fixed;bottom:12px;left:12px;right:12px;z-index:10;margin:auto;max-width:700px;background:#1c3c31;color:white;border-radius:12px;padding:16px;box-shadow:0 4px 24px #0003}#metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.metric{background:#f0f5ef;border-radius:10px;padding:12px}.metric small{display:block;font-size:11px;color:#647c6b}.metric strong{display:block;margin-top:6px;font-size:14px}#warnings{white-space:pre-line}.sr{position:absolute;left:-10000px}[hidden]{display:none!important}#uncertain{background:#fff1d8;border-radius:12px;padding:8px}#uncertain:empty{display:none}#uncertain button{font-size:11px;margin:4px}@media(max-width:600px){section{margin:10px;border-radius:12px;padding:14px}header{padding:14px}#login{margin:24px 12px}#code{font-size:14px}#composer{padding-bottom:max(12px,env(safe-area-inset-bottom))}}\n.message img{display:block;max-width:100%;max-height:420px;object-fit:contain;margin-top:8px}\r\n","type":"text/css; charset=utf-8"},"/admin/app.js":{"body":"const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};\nlet authed=false,selected='',contact=null,contacts=[],messages=[],status={},contactCursor=null,messageCursor=null,loading=false,sending=false,draftId='',noticeTimer;\nfunction notice(text){$('notice').textContent=text;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').hidden=true,7000);}\nfunction signInView(){authed=false;$('login').hidden=false;$('dashboard').hidden=true;}\nasync function api(route,data){const r=await fetch('/admin/api/'+route,{cache:'no-store',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const v=await r.json();if(r.status===401&&route!=='login')signInView();if(!r.ok)throw Error(v.error||'Could not connect');return v;}\nconst cursor=r=>r?'&before='+r._stamp+'&key='+encodeURIComponent(r.key):'';\nasync function command(action,payload,id=crypto.randomUUID()){\n  const queued=await api('commands',{id,action,payload});\n  if(queued.state==='done'){if(!queued.result?.ok)throw Error(queued.result?.error||'Action failed');return queued.result;}\n  for(let i=0;i<24;i++){await new Promise(r=>setTimeout(r,2500));const c=await api('commands/'+id);if(c.state==='done'){if(!c.result?.ok)throw Error(c.result?.error||'Action failed');return c.result;}if(c.state==='expired')throw Error('Action expired without confirmation. Check the chat before trying again.');}\n  throw Error('Still awaiting server confirmation. Check the chat before trying again.');\n}\nfunction inboxView(){selected='';$('chat').hidden=true;$('health').hidden=true;$('inbox').hidden=false;}\nasync function loadContacts(older=false){contacts=await api('contacts?view=recent'+(older?cursor(contactCursor):''));contactCursor=contacts.at(-1);$('moreContacts').hidden=contacts.length<50;const list=$('contacts');list.replaceChildren();if(!contacts.length)list.append(el('p','No customers on this page.'));for(const c of contacts){const b=el('button',undefined,'contact'),name=el('strong',c.name||c.peer.split('@')[0]);if(c.unread)name.append(el('b',String(c.unread)));b.append(name,el('small',c.preview||''));b.onclick=()=>choose(c.peer);list.append(b);}}\nasync function choose(peer){selected=peer;messages=[];messageCursor=null;$('inbox').hidden=true;$('health').hidden=true;$('chat').hidden=false;await loadChat();void command('seen',{peer}).catch(()=>{});}\nasync function loadChat(older=false){if(!selected)return;const peer=selected,r=await api('messages?peer='+encodeURIComponent(peer)+(older?cursor(messageCursor):''));if(selected!==peer)return;contact=r.contact;messages=r.messages;messageCursor=messages.at(-1);$('olderMessages').hidden=messages.length<50;$('chatName').textContent=contact.name||peer.split('@')[0];$('chatDetails').textContent=(contact.optedOut?'Opted out':contact.paused?'Automation paused':'Automation ready')+' · Payment: '+contact.payment.replaceAll('_',' ');$('pause').textContent=contact.paused?'Resume automation':'Pause automation';$('payment').textContent=contact.payment==='verified_by_owner'?'Mark payment pending':'Verify payment';$('send').disabled=sending||contact.optedOut||!status.online;$('reply').disabled=contact.optedOut;const list=$('messages');list.replaceChildren();for(const m of [...messages].reverse()){const b=el('div',undefined,'message '+(m.direction==='out'?'out':'in'));if(m.body)b.append(el('div',m.body,'body'));if(m.url===\"https://rekha-openwa-funnel.phukonbastab2.workers.dev/assets/qr-shahrukh-20261018.png\"){const image=el(\"img\");image.src=m.url;image.alt=\"Shop QR · Shahrukh\";b.append(image);}else if(m.url){const url=new URL(m.url);if(url.origin==='https://pub-e67cd25c4ce94bc38f1077c04b6cfd17.r2.dev'){const a=el('a','View '+m.type);a.href=m.url;a.target='_blank';a.rel='noreferrer';b.append(a);}}if(m.media?.id){const a=el('a','Open customer attachment');a.href='/admin/api/media/'+m.media.id;a.target='_blank';b.append(a);}b.append(el('div',new Date(m.at).toLocaleString()+' · '+m.status,'meta'));list.append(b);}if(!messages.length)list.append(el('p','No stored messages.'));const jobs=$('uncertain');jobs.replaceChildren();for(const j of r.jobs){jobs.append(el('p','Check this uncertain send in WhatsApp before resolving.'));for(const[a,label]of[['sent','It was sent'],['skip','Skip'],['retry','Retry once']]){const b=el('button',label);b.onclick=async()=>{if(!confirm('Have you checked this send in WhatsApp?'))return;try{await command('resolve',{peer,key:j.key,action:a});await loadChat();}catch(e){notice(e.message);}};jobs.append(b);}}}\nconst bytes=n=>Number.isFinite(n)?(n/1024**3>=1?(n/1024**3).toFixed(2)+' GB':(n/1024**2).toFixed(1)+' MB'):'Not measured';\nfunction renderHealth(){const m=status.monitor,list=$('metrics');list.replaceChildren();if(!m){$('warnings').textContent='Waiting for server metrics.';return;}for(const[label,value]of[['Server disk',bytes(m.disk.free)+' free'],['Database',bytes(m.database.bytes)],['Reusable database space',bytes(m.database.reusableBytes)],['Attachments',bytes(m.folders.media.bytes)],['Memory',bytes(m.memory.serverUsed)+' / '+bytes(m.memory.serverTotal)],['Queue',String(m.counts.queued)],['Uncertain sends',String(m.counts.uncertain)],['Backup changes',String(m.counts.backupPending)],['Cloud database',bytes(m.cloud.databaseBytes)+' / '+bytes(m.cloud.d1MaxBytes)],['Retention','90 days'],['Customer storage target','1,000,000'],['Last server check',new Date(m.checkedAt).toLocaleTimeString()]]){const c=el('div',undefined,'metric');c.append(el('small',label),el('strong',value));list.append(c);}$('warnings').textContent=[...m.warnings,m.capacityStatus,'Cloud storage is a shared-database measurement. File sizes refresh about once a minute.'].join('\\n');}\nasync function refresh(){if(loading||!authed)return;loading=true;try{status=await api('status');$('connection').textContent=(status.online?'Server online · ':'Server offline · ')+(status.connection||'unknown');$('summary').textContent=(status.contacts||0)+' customers · '+(status.queued||0)+' queued · backup '+(status.cloud||'waiting');$('toggle').textContent=status.enabled?'Pause funnel':'Enable funnel';$('toggle').disabled=!status.online;renderHealth();if(selected){if(!sending&&!$('reply').value.trim())await loadChat();}else if(!$('inbox').hidden&&!contactCursor?.older)await loadContacts();}catch(e){notice(e.message);}finally{loading=false;}}\n$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('login',{code:$('code').value});$('code').value='';await init();}catch(err){notice(err.message);}};\nasync function init(){try{status=await api('status');authed=true;$('login').hidden=true;$('dashboard').hidden=false;inboxView();await refresh();}catch{signInView();}}\n$('showInbox').onclick=()=>{inboxView();void loadContacts();};$('back').onclick=()=>{inboxView();void loadContacts();};$('showHealth').onclick=()=>{$('inbox').hidden=true;$('chat').hidden=true;$('health').hidden=false;renderHealth();};$('refresh').onclick=()=>authed?refresh():init();\n$('moreContacts').onclick=async()=>{try{await loadContacts(true);if(contactCursor)contactCursor.older=true;}catch(e){notice(e.message);}};$('latestContacts').onclick=()=>loadContacts().catch(e=>notice(e.message));$('olderMessages').onclick=()=>loadChat(true).catch(e=>notice(e.message));\n$('toggle').onclick=async()=>{try{await command('enabled',{enabled:!status.enabled});await refresh();}catch(e){notice(e.message);}};\n$('pause').onclick=async()=>{try{await command('pause',{peer:selected,paused:!contact.paused});await loadChat();}catch(e){notice(e.message);}};\n$('payment').onclick=async()=>{const verified=contact.payment!=='verified_by_owner';if(verified&&!confirm('Have you independently verified the payment reached your account?'))return;try{await command('payment',{peer:selected,verified});await loadChat();}catch(e){notice(e.message);}};\n$('delete').onclick=async()=>{const peer=selected;if(!confirm('Delete stored chat content and attachments? Automation will pause. Cloud deletion follows backup sync. This does not delete messages from WhatsApp phones.'))return;$('delete').disabled=true;try{let r;do{r=await command('delete',{peer,confirm:'DELETE CHAT CONTENT'});}while(r.more);notice('Local content removed. Cloud deletion waits for backup sync.');await loadChat();}catch(e){notice(e.message);}finally{$('delete').disabled=false;}};\n$('composer').onsubmit=async e=>{e.preventDefault();const body=$('reply').value.trim(),peer=selected;if(!body||sending)return;sending=true;$('send').disabled=true;draftId||=crypto.randomUUID();try{await command('send',{peer,body},draftId);if(selected===peer)$('reply').value='';draftId='';notice('Reply queued on the WhatsApp server. Accepted is not delivery confirmation.');await loadChat();}catch(e){notice(e.message+' Retrying this unchanged draft uses the same request ID.');}finally{sending=false;$('send').disabled=!status.online||contact?.optedOut;}};\n$('reply').oninput=()=>{draftId='';};$('logout').onclick=async()=>{try{await api('logout',{});signInView();}catch(e){notice(e.message);}};\nvoid init();setInterval(()=>{if(!document.hidden)void refresh();},10000);\n","type":"text/javascript; charset=utf-8"}};
